use std::fs;
use std::io::Write;
use std::path::Path;
use std::process::Command;
use tempfile::tempdir;
use vb_core::SlotValue;

const NO_PORTS_YAML: &str = "version: velvet-ballistics/v1
name: submit_boundary
when:
  manual: {}
steps:
  - id: build_result
    save:
      output: saved
      value: '42'
  - id: done
    finish:
      result: saved
";

const NUMBER_PORT_YAML: &str = "version: velvet-ballistics/v1
name: submit_number
when:
  manual: {}
inputs:
  count: number
steps:
  - id: build_result
    save:
      output: saved
      value: '42'
  - id: done
    finish:
      result: saved
";

fn subprocess(wf: &str, inp: &str, db: &str, mode: &str) -> std::io::Result<std::process::Output> {
    Command::new(env!("CARGO_BIN_EXE_velvet-ballistics"))
        .args(["submit", wf, "--input-bin", inp, "--db", db, "--durability", mode])
        .output()
}

fn write_file(dir: &tempfile::TempDir, name: &str, data: &[u8]) -> std::io::Result<String> {
    let path = dir.path().join(name);
    let mut f = fs::File::create(&path)?;
    f.write_all(data)?;
    Ok(path.to_string_lossy().to_string())
}

fn db_path(dir: &tempfile::TempDir) -> String {
    dir.path().join("db").to_string_lossy().to_string()
}
